"""Undo, redo and history (docs/undo.md)."""

from binkeep import journal
from binkeep.bins import normalize
from binkeep.errors import DataError, Refused


def _is_int(x) -> bool:
    return isinstance(x, int) and not isinstance(x, bool)


class Stacks:
    """The done and undone stacks, worked out from the journal (undo.md, section 2)."""

    def __init__(self, entries: list[dict]):
        self.done: list[dict] = []
        self.undone: list[tuple[dict, dict]] = []  # (operation, undo line)
        self.dropped: list[dict] = []
        self.operations: list[dict] = []
        for e in entries:
            op = e["op"]
            if op in journal.OPS:
                self.operations.append(e)
                self.done.append(e)
                self.dropped.extend(o for o, _ in self.undone)
                self.undone = []
            elif op == "undo":
                target = self._target(e)
                if not self.done or self.done[-1]["seq"] != target:
                    raise DataError("journal", f"#{e['seq']}: undo does not match the top of done")
                self.undone.append((self.done.pop(), e))
            elif op == "redo":
                target = self._target(e)
                if not self.undone or self.undone[-1][0]["seq"] != target:
                    raise DataError("journal", f"#{e['seq']}: redo does not match the top of undone")
                self.done.append(self.undone.pop()[0])

    @staticmethod
    def _target(e: dict) -> int:
        t = e.get("target")
        if not _is_int(t):
            raise DataError("journal", f"#{e['seq']}: no target")
        return t

    def status(self, e: dict) -> str:
        if any(e is o for o, _ in self.undone):
            return "undone"
        if any(e is o for o in self.dropped):
            return "dropped"
        return "barrier" if e["op"] == "fix" else "done"


def _effects(e: dict) -> list[tuple[str, int, int]]:
    raw = e.get("effects")
    if not isinstance(raw, list):
        raise DataError("journal", f"#{e['seq']}: no effects")
    out = []
    for x in raw:
        if (not isinstance(x, dict) or not isinstance(x.get("bin"), str)
                or not _is_int(x.get("before")) or not _is_int(x.get("after"))):
            raise DataError("journal", f"#{e['seq']}: bad effect")
        out.append((normalize(x["bin"]), x["before"], x["after"]))
    return out


def _v1_changes(ctx, e: dict) -> list[tuple[str, int]]:
    """Format 1: (bin, delta to apply when undoing), in the order they are taken back."""
    try:
        op = e["op"]
        if op == "receive":
            units = e["qty"]
            if e.get("uom") == "pk":
                if e["sku"] not in ctx.items:
                    raise Refused("unknown-sku", f"no item {e['sku']}")
                units *= ctx.items[e["sku"]].pack_size
            return [(normalize(e["bin"]), -units)]
        if op == "issue":
            return [(normalize(b), q) for b, q in reversed(e["picks"])]
        if op == "move":
            return [(normalize(e["to"]), -e["qty"]), (normalize(e["from"]), e["qty"])]
    except (KeyError, TypeError, ValueError, AttributeError):
        pass
    raise DataError("journal", f"#{e['seq']}: malformed format 1 line")


def _step(ctx, store, stacks: Stacks, redo: bool, seq: int):
    """One step against `store` (modified) and `stacks` (modified). Returns the new entry."""
    if redo:
        if not stacks.undone:
            raise Refused("nothing-to-redo", "nothing to redo")
        e, undo_line = stacks.undone[-1]
        sets = [(b, before) for b, before, _ in reversed(_effects(undo_line))]
    else:
        if not stacks.done:
            raise Refused("nothing-to-undo", "nothing to undo")
        e = stacks.done[-1]
        if e["op"] == "fix":
            raise Refused("barrier", "the latest operation is a fix")
        if e.get("v") == 2:
            sets = [(b, before) for b, before, _ in reversed(_effects(e))]
        elif e["op"] == "count":
            raise Refused("irreversible", "a format 1 count cannot be undone")
        else:
            sets = None
            changes = _v1_changes(ctx, e)
    sku = e.get("sku", "")
    codes = [b for b, _ in sets] if sets is not None else [b for b, _ in changes]
    for c in codes:
        if c not in ctx.bins:
            raise Refused("unknown-bin", f"no bin {c}")
    effects = []
    if sets is not None:
        for code, qty in sets:
            before = store.qty(sku, code)
            store.restore(sku, code, qty)
            effects.append({"bin": code, "before": before, "after": qty})
    else:
        for code, delta in changes:
            before = store.qty(sku, code)
            store.restore(sku, code, before + delta)
            effects.append({"bin": code, "before": before, "after": before + delta})
    if redo:
        stacks.done.append(stacks.undone.pop()[0])
    else:
        stacks.undone.append((stacks.done.pop(), None))
    line = journal.entry(seq, "redo" if redo else "undo", ctx.by, sku, target=e["seq"], effects=effects)
    if not redo:
        stacks.undone[-1] = (e, line)
    return line, e


def run(ctx, steps: int, redo: bool):
    """Returns (store, new entries, [(entry, operation)])."""
    stacks = Stacks(ctx.entries)
    store = ctx.store.copy()
    seq = journal.next_seq(ctx.entries)
    lines, done = [], []
    for _ in range(steps):
        line, e = _step(ctx, store, stacks, redo, seq)
        seq += 1
        lines.append(line)
        done.append((line, e))
    return store, lines, done
